actions.script:
let answer = {applied: false}
const check = ec.service.sync().name('ironstone.maintenance.AccessServices.check#Record')
    .parameters({appRoot, recordType: 'workOrder', recordId: workEffortId}).requireNewTransaction(true).call() || {}
if (!ec.message.hasError() && check.recordId) {
    const thru = Number(context.thruDate)
    const out = ec.service.sync().name('mantle.other.LocationShareServices.create#RecordGuestShare').requireNewTransaction(true)
        .parameters({recordType: 'workOrder', recordId: workEffortId, thruDate: Number.isFinite(thru) && thru > 0 ? new Date(thru) : null,
            precisionEnumId: context.precisionEnumId === 'LspApproximate' ? 'LspApproximate' : 'LspExact',
            purposeText: String(context.purposeText || '').trim().slice(0, 200) || null}).call() || {}
    if (!ec.message.hasError()) answer = {applied: true, shareId: out.shareId, thruDate: out.thruDate ? ec.user.timestampMillis(out.thruDate) : null,
        mailSent: !!out.mailSent, approximate: context.precisionEnumId === 'LspApproximate'}
}
if (ec.message.hasError()) answer.reason = ec.message.getErrorsString().replace(/^[A-Z][A-Z0-9_]+: /, '')
ec.message.clearErrors()
ec.web.sendJsonResponse(answer)
